import{_ as a,c as s,o as t,j as S}from"./chunks/framework.Ch_PcVtW.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART3/2.md","filePath":"ja-jp/Management2/PART3/2.md"}'),n={name:"ja-jp/Management2/PART3/2.md"};function A(E,e,N,H,o,I){return t(),s("div",null,[...e[0]||(e[0]=[S("p",null,'2023/12 Nissyとのコラボ曲で 届けたかったテーマとは? #DUNK #リーダーシップ #他社とのコラボ #キャリア #アイドル論 #SNS カルチャー 「キャリアと歴史がある自分こそはちゃんと反論や否定 をしないといけない」 2023年12月2日、3日に京セラドーム大阪にてSKY-HI 主宰のライブイベント 「D.U.N.K. Showcase in KYOCERA DOME OSAKA」 が開催された。 日本テレ ビとタッグを組んだダンス&ボーカルの大型プロジェクト 「D.U.N.K.」のライ ブとしては23年3月に続き2度目。 プロジェクトが掲げる「良いものは良い /もうダンス&ボーカルシーンに垣根も差別も必要ない/ここを歴史のター ニングポイントにしよう」 の具現化はパワーアップし、所属事務所やレーベ ルの枠を超えた12組のアーティストがステージに立った。 ダンス&ボーカルのコラボステージを盛り込んだイベントは、過去にないも の。1度目のショーケース後、 SKY-HI は「ようやくどんなイベントなのかを伝 えやすくなると思う」と話していたが、2回目を終えた今、前回と1番違った のはそこだったと振り返る。 このタイミングでの京セラドームでの開催は、企画を進める際 から決まっていたことで、 特にドーム公演に向けての気負いはあり ませんでした。 初回との違いとして1番大きかったのは、間違いな オファーしやすかった点が挙げられます。というのも、前回の公 演があったことと影響力が生まれたことで、 どういうイベントかが明 確になったことでした。 今回の「D.U.N.K. Showcase」で絶対にやりたかったのは、 1 回目になかった新しいコラボレーションでした。 RIEHATAと SOTA(BE:FIRST)のダンス、ラップラインが集結する瞬間、西 島(隆弘/Nissy)との作品、3つのコラボのために新曲を作り、そ の準備は大変でしたね。 RIEHATAとSOTAのコラボで、 RIEHATA が 「自分でバー スを蹴りたい(ラップをしたい)」って言ってくれたのは、サプライズ ではありましたが、ありがたかったです。 もともと既存の曲でコラボ するのではなく、ちゃんとそのためのものを作ることはしたかったの ですが、一気にアイデアも膨らみました。 書き下ろした新曲 『Back on the stage』は音源を出すのか、違うイベントでも使うとか・・・は、 まだ言えません。 RIEHATA は BTS や BLACKPINK、 TWICEなど多くのアーティストのコレオグラ フィーを作るトップダンサーだ。 一方のSOTAも、ダンスの世界大会で4回の 優勝経験を持つ。 2人のワールドクラスのダンサーがステージを作った。 新 曲制作以外にも難しさを感じたことがあったという。 それは、コラボのため に他事務所所属のアーティストにも時間と労力を割いてもらう必要が生まれ ることだった。 コラボレーションのオファーを受けた側の人や会社がどう感じる かを気にし続ける時間が続くという困難さはありました。前回は初 めてということもあり、BMSGのアーティストが中心になってコラボ を進めたのでスムーズだったのですが、2回目以降はイベントの 意義として、極力よその事務所の方が参加するコラボステージも 増やしたいと考えていました。 出演していただいた皆さんに何かしらコラボに参加していただき 「一緒に作った」という気持ちになれると良いなと思っていたので すが、一方でそれは皆さんに新規オファーをしなくてはいけないと いうこと。お声を掛ければ喜んでくださいますが、それは仕事を増 やすことにもなる。しかも、これは良いことなのですが、テレビの 音楽番組などでも事務所の枠を超えたコラボの機会がいっせいに 増えていて、アーティストにとってはそのような業務量が増えている こともあります。そうした狭間で心苦しさがありました。 ただ、やれば見てくださった方は大きく沸きますし、その沸き方 は幸せで楽しいものだと思うんです。 そうした空気は 「D.U.N.K.」 が1番大事にしたいものでもあるので、他の事務所さん側、アー ティストさん側も懸念なく楽しんでいただくためにはどうすればいい かというのは大事かつ大きな仕事でしたし、 大変でもありましたね。 アイドルにおけるラップとは ラップコラボには、LIL LEAGUE や THE JET BOY BANGERZ (以上、LDH)、BE :FIRST らが出演した。ラップコラボは予想していなかったが、メンバーのス キルと何よりステージを見れば、さもありなんと思わされたのと同時に、今 の日本のダンス&ボーカルグループのなかでラップの占める位置の高さに 改めて気づかされた。 さらには今後、ダンス&ボーカルグループのラッパー を集めたイベントができるのではないかという期待も膨らんだ。 ラップコラボのステージを作ったのは、単純にグループを支え るラッパーが世界的に多いからです。 いつかラッパーを集めたイベントもしたいなとか、ちょっと思った りもしました。 (韓国のラップサバイバル番組) 『SHOW ME THE MONEY (以下、SMTM) 』 に近いような場が日本にもあったほうが いいので、本当にそれは思います。 そういう夢を持てるといいじゃな いですか。 14歳から19歳までの LIL LEAGUEのメンバーもすご くスキルが高いですし、 『SMTM』 のようなイベントに出て、あの 年齢であのスキルを見せたら、大きな反響を得そうですよね。 実際のところ、ラップは技術以外のほうが大事なアートフォー ムでもあるので一概には言えないですけど、 当然、 技術というもの も存在していて、自分にとってそこの追求は大事な要素です。 特 にラップを語るうえで欠かしてはいけない、カルチャーとしてのHI PHOP にリスペクトを示し、学ぶ姿勢を示すことは必要だと思うん ですけど、それを前提にしたうえで、近年のアイドルグループのラ ッパーの多くは、 カルチュアルな意味でのHIPHOPのバックグ ラウンドが少ないからこそ、精神性を大事にし、よく学び、技術を 磨く傾向にあると思います。 それがアイドル出身のラッパーの面白 さだと感じることが多いですね。 『SMTM』でも過去にアンダーグラウンドのラッパーを差し置い てアイドルラッパーが優勝することが続いたりしたのも興味深いこと だと思いますし、今のシーンのミドルティーンからハイティーンの 中でもLIL LEAGUE は相当ラップがうまく、見ていてうれしかっ たですね。HIPHOPとはまた別だけど無関係ではない、独特の カルチャーやシーンが生まれそうだと思っていますし、それはちょう ど僕の生きた証にもなります。 キャリアがあるから言えること AAA時代からの盟友でもある Nissyとのでのコラボでは、 SKY-HIxNissyの 『SUPER IDOL 』 が初披露された。 ほぼ20年のキャリアを持つ2人が36歳、 37歳で "スーパーアイドル"としての生き様と価値観をシニカルに歌う、 アグ レッシブな曲だ。 ドープなトラックに乗せた強いメッセージ性を感じる歌詞は、 まさにアイドル的な側面を持つ若いグループの前、 また彼らを目当てに集ま った観客の前で披露するのにふさわしい1曲だったと言えるだろう。 「キャリアがあるから言えること」は間違いなくあると思います。歌 って、「その人が歌う意味があるべき必要」 は絶対的にあると思う んです。それはロックバンドでもHIPHOP でもアイドルでもそうだと 自分は思うんですが。 ただ、たぶんHIPHOP が誕生して広まっていくうちに、「その人 が歌う意味がある」という意味合いは強くなっています。現在のア イドルシーンでもBTS に象徴されるように、 意志が見えるアイドル のほうが強いし、 実際に成功していると思います。 話を戻すと、もともと西島と一緒に曲を作ることは 「D.U.N.K.」 の前から決めていたし、 西島とやるならこのタイトルだろうと自分 の中では明確にありました。 純粋に面白そうだなというのが1つ、 西島が隣にいないと言わないことであるのが1つ、そして1番大事 なのが、自分たちが少なからず現役のアイドルに伝えられることが あるだろうというのが1つです。 なりわい 最後のものに関して言うと、「歌って踊る」 という生業は、スポ ーツ選手よりは長いかもしれないけれども、 寿命があるものだと思 っています。 自分も西島も、あと3年もするとフェーズが確実に変わ ります。 20代でできたことが30代でできなくなる一方で、キャリア のある今だからできること、やるべきこともあります。2人とも普段は それぞれそう自認しながら活動していると思いますが、 2人でやるな らテーマはここだろうなという気がしました。 「D.U.N.K.」に出演したアーティストのために作ったわけではあ りませんが、事務所も国も関係なく、頑張っている子たちを応援し たいという気持ちは常に持っているので、そんな彼らの姿を思い描 いた曲であるのかもしれないです。 10代、20代あたりのキャリアだと「思っても言わないようにする」 「思っても言っちゃいけないと思い込む」ことが多いと思うんです。 そ こに対しても大人の責任として、彼らが意志を表に出しやすい、意 見を表明してもいい環境なりを作っていくほうがいいと常に思ってま す。 まずは 届くべきところに届くといいなと思いますし、さらに言え ば、日本でダンス&ボーカルグループにつきまとう 「アイドル/ アーティスト論争」 は一生かけても終わらせたいなという気持ちは 強いです。 「押し黙る」 を正解にしない 音楽番組で2人のステージが放送された後、SNSにはこの曲の歌詞をつな ぎ合わせ、その意味を曲解させるような1つの投稿が広がった。それに対し、 SKY-HI は即座に抗議に出た。 SNS カルチャーが始まってから、ねつ造した情報なり画像が広 まることって本当に多いじゃないですか。僕自身、表に立つ人間と してのキャリアは長く、世の中に対してこうあるべきという提示や再 168 Nissyとのコラボ曲ではあ 定義をしていく立場なので、 発言に対しての誤解や曲解は常につ きまとってきました。 よくあることなので、「そういうもんだよね」と流し ていることも多いですが、 今回ばかりは悪質に感じたので明確に 否定したんです。 これに関連して言えば、「現代は文章を読めない人が本当に多 く、自分の感情を満たすのに近しい文字を見つけて、勝手に文 章を自分の中で作ってしまう」とどこかで見掛けましたが、自分も 本当にそう思うことが多いです。ただ僕は作詞家でもあるから、そ こは文字や作品で伝えていくことを諦めちゃいけない。 同時に、「押 し黙る」が正解になりがちな若いアーティストと違って、キャリアと 歴史がある自分こそはちゃんと反論や否定をしないといけない、総 じて、常に読まれるに値する意義を提示することを生涯頑張り続け なければいけないと思っています。 どんなに傷ついても(笑)。 最後に、 今後の 「D.U.N.K.」 はどこへ向かうのかを尋ねた。 今の形の 「D.U.N.K.」 って、あと何回やれるんだろうなってい うのは、正直に思いますね。 「BMSG FES」もしかりですが、自 分のアーティストとしてのキャリアとかが変わったら、イベントの形 も変わるわけじゃないですか。ただ、それがどういうふうに変わるの かまでは、 「D.U.N.K.」 に関しては想像がつかないんです。 とい うより、 まだ想像しきれてないんですよね。 次の開催スケジュール もまだ決まっていませんが、それでも 「こういうことをやるべきだ」と いうものは自分の中にあります。近い将来、徐々に形を変えていく のか····いや、これは時流に寄るところもあるので本当に分からない ですね。',-1)])])}const K=a(n,[["render",A]]);export{r as __pageData,K as default};
